// The Merge node returns an array of items, each holding an "offers" list
// Structure: [ { offers: [...] }, { offers: [...] } ]

let allOffers = [];

// Merge output (array of items)
if (Array.isArray($input.all())) {
  // Collect the offers of every merged item
  $input.all().forEach(item => {
    if (item.json && item.json.offers && Array.isArray(item.json.offers)) {
      allOffers = allOffers.concat(item.json.offers);
    }
  });
}
// Fallback: single object
else if ($json.offers && Array.isArray($json.offers)) {
  allOffers = $json.offers;
}

const offers = allOffers;

function extractSalary(text){
    if(!text) return 0;
    const nums = text.match(/\d+/g);
    if(!nums) return 0;
    return Math.max(...nums.map(Number));
}

// ============================================================
// Deduplicate by company (best salary kept)
// ============================================================
const companies = {};
for(const offer of offers){
    const company = (offer.entreprise || "").trim().toLowerCase();
    if(!company) continue;
    const salary = extractSalary(offer.remuneration);
    if(!companies[company] || salary > companies[company].salary_num){
        companies[company] = { ...offer, salary_num: salary };
    }
}
const result = Object.values(companies);

// ============================================================
// MECHANICAL PRE-FILTER (before calling the LLM, to save tokens)
// ============================================================

const EXCLUDED_TITLE_KEYWORDS = [
  // Medical
  'médecin', 'cardiologue', 'psychiatre', 'chirurgien', 'infirmier',
  'pharmacien', 'kinésithérapeute', 'orthophoniste', 'aide-soignant',
  // IT
  'développeur', 'devops', 'data scientist', 'cybersécurité', 'informatique',
  'ingénieur logiciel', 'ingénieur développement',
  // ERP / complex IT systems
  'consultant erp', 'consultant sap', 'consultant fonctionnel',
  'chef de projet erp', 'chef de projet sap', 'chef de projet si',
  'administrateur sap', 'intégrateur erp', 'mco erp',
  // Operational / temp roles
  'ouvrier', 'cariste', 'magasinier', 'opérateur', 'monteur',
  'manutentionnaire', 'conducteur de ligne', 'agent de production',
  'planificateur', 'ordonnancement', 'préparateur de commandes',
  'chauffeur', 'livreur'
];

const EXCLUDED_COMPANY_KEYWORDS = [
  // Generic sectors
  'association', 'fondation',
  'mutuelle', 'mutuelles', 'assurance', 'assurances',
  'ehpad', 'clinique', 'hôpital', 'hopital', 'chu', 'centre hospitalier',
  'cabinet', 'conseil', 'consulting', 'engineering', 'ingénierie',
  'hôtel', 'hotel', 'restaurant', 'auberge',
  'immobilier', 'immobilière',
  'mairie', 'urssaf', 'cci', 'afpa', 'pôle emploi', 'collectivité',
  'banque', 'crédit', 'caisse d\'épargne',
  // Temp agencies / confidential postings (partial match)
  'interim', 'intérim', 'confidentiel',
  // Add your own company names to exclude here
  // (the private blacklist used in production is not published)
];

const EXCLUDED_DESC_KEYWORDS = [
  'assistance technique', 'engineering services',
  'médico-social', 'établissement de santé', 'établissement médico-social',
  'compagnie d\'assurance', 'sinistres', 'expertise assurance',
  'cabinet de conseil', 'cabinet de recrutement',
  'agence immobilière', 'syndic',
  'secteur associatif', 'association loi 1901',
  'collectivité territoriale', 'service public', 'fonction publique',
  'hébergement touristique', 'restauration collective',
  // ERP / complex IT
  'sap', 'erp', 'oracle', 'salesforce', 'dynamics 365', 'progiciel',
  'intégration système d\'information', 'migration erp',
  'éditeur de logiciel', 'éditeur logiciel'
];

function textIncludesAny(text, keywords) {
  return keywords.some(kw => text.includes(kw));
}

function shouldPreFilter(item) {
  const titre = (item.titre || '').toLowerCase();
  const entreprise = (item.entreprise || '').toLowerCase();
  const desc = (item.description || '').toLowerCase();

  if (textIncludesAny(titre, EXCLUDED_TITLE_KEYWORDS)) return true;
  if (textIncludesAny(entreprise, EXCLUDED_COMPANY_KEYWORDS)) return true;
  if (textIncludesAny(desc, EXCLUDED_DESC_KEYWORDS)) return true;

  return false;
}

const filtered = result.filter(item => !shouldPreFilter(item));

return [{
    json: {
        TOTAL_AFTER_DEDUPE: filtered.length,
        OFFERS: filtered
    }
}];

